fn flip_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| {
            if c.is_ascii_alphabetic() {
                // Flip the case of the character
                if c.is_lowercase() {
                    c.to_uppercase().next().unwrap() // Convert to uppercase
                } else {
                    c.to_lowercase().next().unwrap() // Convert to lowercase
                }
            } else {
                c // Keep the character unchanged
            }
        })
        .collect() // Collect the results into a Vec<char>
}

fn main() {
    let input = vec!['H', 'e', 'l', 'l', 'o', ' ', 'W', 'o', 'r', 'l', 'd', '!'];
    let output = flip_case(input);
    println!("{:?}", output); // Output: ['h', 'E', 'L', 'L', 'O', ' ', 'w', 'O', 'R', 'L', 'D', '!']
}